import{_ as e,o as t,c as o,a0 as l}from"./chunks/framework.B7o6dWmz.js";const p=JSON.parse('{"title":"博客是怎么建起来的：两天建站记","description":"","frontmatter":{},"headers":[],"relativePath":"posts/build-log.md","filePath":"posts/build-log.md","lastUpdated":null}'),r={name:"posts/build-log.md"};function d(i,a,s,n,c,u){return t(),o("div",null,[...a[0]||(a[0]=[l('<h1 id="博客是怎么建起来的-两天建站记" tabindex="-1">博客是怎么建起来的：两天建站记 <a class="header-anchor" href="#博客是怎么建起来的-两天建站记" aria-label="Permalink to &quot;博客是怎么建起来的：两天建站记&quot;">​</a></h1><blockquote><p>第一篇正经文章，记录一下这个博客从零到上线的过程。</p></blockquote><h2 id="_10-月-18-日-买域名、搭架子" tabindex="-1">10 月 18 日：买域名、搭架子 <a class="header-anchor" href="#_10-月-18-日-买域名、搭架子" aria-label="Permalink to &quot;10 月 18 日：买域名、搭架子&quot;">​</a></h2><p>先在 GoDaddy 买了 <code>wloczlw.tech</code>，把 nameserver 换到 Cloudflare，解析几分钟就全网生效了。</p><p>博客本体用 VitePress 写的，静态页面，丢到 GitHub Pages 上。Cloudflare 里配好四条 A 记录和一条 www 的 CNAME，自定义域名一绑，网站就通了。</p><h2 id="证书卡了一下" tabindex="-1">证书卡了一下 <a class="header-anchor" href="#证书卡了一下" aria-label="Permalink to &quot;证书卡了一下&quot;">​</a></h2><p>GitHub 的 HTTPS 证书一直签不下来。解决办法很粗暴：把自定义域名删掉重新加一遍，触发它重新验证，证书就有了，顺手开了强制 HTTPS。</p><h2 id="换了两套皮肤" tabindex="-1">换了两套皮肤 <a class="header-anchor" href="#换了两套皮肤" aria-label="Permalink to &quot;换了两套皮肤&quot;">​</a></h2><p>第一版是鸢尾蓝紫，渐变标题加特性卡片。第二版照着一张红日黑浪的图彻底重做：赤红 <code>#c1272d</code> 做品牌色，宣纸米白底，炭黑深色模式，整张图铺成首页横幅。现在这个样子我很喜欢。</p><p>中间还踩了个坑：逐个文件推送会触发太多次 Pages 构建导致失败，改成一次提交推送就好了。</p><h2 id="_10-月-19-日-解决国内访问" tabindex="-1">10 月 19 日：解决国内访问 <a class="header-anchor" href="#_10-月-19-日-解决国内访问" aria-label="Permalink to &quot;10 月 19 日：解决国内访问&quot;">​</a></h2><p>早上发现从国内打不开，报&quot;无法连接服务器&quot;。DNS 和源站都没问题，就是到 GitHub Pages 的线路不太行。解决办法：把 Cloudflare 的代理打开（橙色云），SSL 模式设成 Full (strict)，让访问走 Cloudflare 的节点中转。</p><h2 id="就这样" tabindex="-1">就这样 <a class="header-anchor" href="#就这样" aria-label="Permalink to &quot;就这样&quot;">​</a></h2><p>两天时间，博客开张。以后想到什么就写下来，慢慢来。</p>',14)])])}const _=e(r,[["render",d]]);export{p as __pageData,_ as default};
